import { getResolvedApiBaseUrl } from '@/core/global-data/constants.data';

/** Builds absolute URL for a path stored under Laravel `storage/app/public` (or already absolute). */
export function resolvePublicStorageUrl(path: string | null | undefined): string | null {
    if (!path || typeof path !== 'string') {
        return null;
    }
    const trimmed = path.trim();
    if (!trimmed) {
        return null;
    }
    if (/^https?:\/\//i.test(trimmed)) {
        return trimmed;
    }
    const api = getResolvedApiBaseUrl();
    const origin = api.replace(/\/api\/?$/, '');
    const clean = trimmed.replace(/^\/+/, '').replace(/^storage\//, '');
    return `${origin}/storage/${clean}`;
}
