import { ColumnDef } from '@tanstack/react-table';
import { cn } from '@/lib/utils';

export type HolidayRequestRow = {
    id: number;
    vacation_type?: string | null;
    status?: string | null;
    start_date?: string | null;
    end_date?: string | null;
};

export const columns: ColumnDef<HolidayRequestRow>[] = [
    {
        accessorKey: 'vacation_type',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                نوع الإجازة
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.vacation_type ?? '—'}
            </div>
        ),
    },
    {
        accessorKey: 'start_date',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                من
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.start_date ?? '—'}
            </div>
        ),
    },
    {
        accessorKey: 'end_date',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                إلى
            </div>
        ),
        cell: ({ row }) => (
            <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px] px-4 py-3">
                {row.original.end_date ?? '—'}
            </div>
        ),
    },
    {
        accessorKey: 'status',
        header: () => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                الحالة
            </div>
        ),
        cell: ({ row }) => {
            const s = row.original.status ?? '';
            return (
                <div className="text-xs font-medium tracking-normal leading-[115%] px-4 py-3">
                    <p
                        className={cn('p-1 w-fit rounded-sm', {
                            'bg-[#DAF8E6] text-[#1A8245]': s === 'approved',
                            'bg-[#FEEBEB] text-[#E10E0E]': s === 'rejected',
                            'bg-amber-100 text-amber-900': s === 'pending' || !s,
                        })}
                    >
                        {s || '—'}
                    </p>
                </div>
            );
        },
    },
];
