import NormalCard from '@/components/cards/NormalCard';
import ReportSection from './ReportSection';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Shield, ShieldOff } from 'lucide-react';
import { useEffect, useState } from 'react';

type InsuranceRow = {
    certificate_type?: string | null;
    amount?: number | string | null;
    start_date?: string | null;
};

export default function Insurances({ employeeId }: { employeeId: number }) {
    const [row, setRow] = useState<InsuranceRow | null | 'none'>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({ endpoint: endpoints.insurance.employeeShow(employeeId) });
                const payload = res.data?.data;
                if (!cancelled) {
                    if (payload === null || payload === undefined) {
                        setRow('none');
                    } else {
                        setRow(payload as InsuranceRow);
                    }
                }
            } catch {
                if (!cancelled) setRow('none');
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    if (row === 'none') {
        return (
            <ReportSection icon={ShieldOff} title="التأمينات الاجتماعية" description="لا توجد بوليصة مسجّلة لهذا الموظف حالياً.">
                <div className="flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-200 bg-slate-50/60 px-4 py-10 text-center">
                    <ShieldOff className="mb-3 h-10 w-10 text-slate-400" aria-hidden />
                    <p className="font-cairo text-sm text-slate-600">لا توجد بيانات تأمين لعرضها.</p>
                </div>
            </ReportSection>
        );
    }

    return (
        <ReportSection icon={Shield} title="التأمينات الاجتماعية" description="بيانات الشهادة أو البوليصة إن وُجدت.">
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4">
                <NormalCard content={row?.certificate_type ?? '—'} title="نوع الشهادة / التأمين" />
                <NormalCard content={row?.amount != null ? `${row.amount} ر.س` : '—'} title="المبلغ" />
                <NormalCard content={row?.start_date ?? '—'} title="تاريخ البداية" className="sm:col-span-2" />
            </div>
        </ReportSection>
    );
}
