import NormalCard from '@/components/cards/NormalCard';
import ReportSection from './ReportSection';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { Wallet } from 'lucide-react';
import { useEffect, useState } from 'react';

type MonthSalary = {
    total_allowances?: number;
    total_deductions?: number;
    net_salary?: number;
    total_salary?: number;
};

export default function Salary({ employeeId }: { employeeId: number }) {
    const [data, setData] = useState<MonthSalary | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const res = await apiGet({
                    endpoint: endpoints.financeEmployee.currentMonthSalaryFor + employeeId,
                });
                const payload = res.data?.data ?? res.data;
                if (!cancelled && payload && typeof payload === 'object') {
                    setData(payload as MonthSalary);
                }
            } catch {
                if (!cancelled) setData(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [employeeId]);

    const basic = data?.total_salary ?? '—';
    const allowances = data?.total_allowances ?? '—';
    const deductions = data?.total_deductions ?? '—';
    const net = data?.net_salary ?? '—';

    const fmt = (v: number | string) => (typeof v === 'number' ? `${v} ر.س` : String(v));

    return (
        <ReportSection
            icon={Wallet}
            title="الراتب والماليات"
            description="أرقام تقريبية للشهر الحالي حسب بيانات المالية المتاحة."
        >
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4">
                <NormalCard content={fmt(basic)} title="الراتب الأساسي" />
                <NormalCard content={fmt(allowances)} title="إجمالي البدلات" />
                <NormalCard content={fmt(net)} title="صافي الراتب (الشهر الحالي)" className="sm:col-span-2" />
                <NormalCard content={fmt(deductions)} title="خصومات الشهر" />
            </div>
        </ReportSection>
    );
}
