import NormalCard from '@/components/cards/NormalCard';
import ReportSection from './ReportSection';
import { PieChartComponent } from '@/components/charts/PieChart';
import { ChartConfig } from '@/components/ui/chart';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { useSelfServiceEmployee } from '@/features/selfServices/context/SelfServiceEmployeeContext';
import { Landmark } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import List from './List';

type Counts = { total: number; approved: number; rejected: number; pending: number };

export default function Loans({ employeeId }: { employeeId: number }) {
    const { isPrivileged } = useSelfServiceEmployee();
    const [counts, setCounts] = useState<Counts | null>(null);

    useEffect(() => {
        let cancelled = false;
        (async () => {
            try {
                const queryParams: Record<string, string | number> = { mine: 1 };
                if (isPrivileged) {
                    queryParams.employee_id = employeeId;
                }
                const res = await apiGet({
                    endpoint: endpoints.loan.dashboard,
                    queryParams,
                });
                const d = res.data?.data as Counts | undefined;
                if (!cancelled && d) {
                    setCounts({
                        total: Number(d.total) || 0,
                        approved: Number(d.approved) || 0,
                        rejected: Number(d.rejected) || 0,
                        pending: Number(d.pending) || 0,
                    });
                }
            } catch {
                if (!cancelled) setCounts(null);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [employeeId, isPrivileged]);

    const chartData = useMemo(() => {
        if (!counts) return [];
        return [
            {
                days: 'مقبولة',
                visitors: counts.approved,
                fill: 'var(--color-available)',
            },
            {
                days: 'مرفوضة',
                visitors: counts.rejected,
                fill: 'var(--color-leased)',
            },
            {
                days: 'قيد المراجعة',
                visitors: counts.pending,
                fill: 'hsl(var(--primery-blue-200))',
            },
        ].filter((x) => x.visitors > 0);
    }, [counts]);

    const chartConfig = {
        visitors: { label: 'Visitors' },
        available: { label: 'مقبولة', color: 'hsl(var(--primery-blue-400))' },
        leased: { label: 'مرفوضة', color: 'hsl(var(--primery-blue-100))' },
    } satisfies ChartConfig;

    const listText = counts
        ? [`إجمالي الطلبات: ${counts.total}`, `مقبولة: ${counts.approved}`, `مرفوضة: ${counts.rejected}`, `قيد المراجعة: ${counts.pending}`]
        : [];

    return (
        <ReportSection
            icon={Landmark}
            title="القروض"
            description="ملخص حالة طلبات القروض الشخصية مع توزيع الحالات."
        >
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4">
                <NormalCard content={counts ? String(counts.total) : '—'} title="إجمالي الطلبات" />
                <NormalCard content={counts ? String(counts.approved) : '—'} title="طلبات مقبولة" />
                <NormalCard content={counts ? String(counts.pending) : '—'} title="قيد المراجعة" />
                <NormalCard content={counts ? String(counts.rejected) : '—'} title="مرفوضة" />
            </div>
            <div className="mt-6 flex flex-col items-stretch gap-8 lg:flex-row lg:items-start lg:justify-between lg:gap-10">
                <List text={listText} className="min-w-0 flex-1 ps-4 sm:ps-5" />
                {chartData.length > 0 ? (
                    <div className="flex w-full shrink-0 justify-center lg:w-auto lg:max-w-[min(100%,280px)]">
                        <PieChartComponent chartData={chartData} chartConfig={chartConfig} />
                    </div>
                ) : (
                    <p className="text-center text-sm text-slate-500 lg:text-start">لا توجد بيانات كافية للرسم البياني.</p>
                )}
            </div>
        </ReportSection>
    );
}
