import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import NormalCard from '@/components/cards/NormalCard';
import ReportSection from './ReportSection';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { openPrintableAttendanceMonthly, openPrintableReport } from '@/features/selfServices/utils/printReport';
import { CalendarClock, Clock3, Printer } from 'lucide-react';
import { useCallback, useEffect, useMemo, useState } from 'react';

type Stats = {
    total_days?: number;
    present?: number;
    absent?: number;
    late?: number;
    leave?: number;
};

type DayAttendance = {
    status?: string;
    check_in?: string | null;
    check_out?: string | null;
    notes?: string | null;
};

type MonthlyEmployeeRow = {
    name?: string;
    branch?: string;
    position?: string;
    summary?: {
        total_days?: number;
        present?: number;
        absent?: number;
        late?: number;
        leave?: number;
    };
    attendance?: Record<string, DayAttendance>;
};

function statusAr(code: string): string {
    const m: Record<string, string> = {
        present: 'حاضر',
        absent: 'غائب',
        late: 'متأخر',
        leave: 'إجازة',
    };
    return m[code] ?? code;
}

export default function Attendance({ employeeId }: { employeeId: number }) {
    const [stats, setStats] = useState<Stats | null>(null);
    const [employeeName, setEmployeeName] = useState<string>('');
    const [branchName, setBranchName] = useState<string>('');
    const [monthly, setMonthly] = useState<MonthlyEmployeeRow | null>(null);
    const [periodLabel, setPeriodLabel] = useState<string>('');

    const now = useMemo(() => new Date(), []);
    const month = now.getMonth() + 1;
    const year = now.getFullYear();

    useEffect(() => {
        let cancelled = false;
        setPeriodLabel(`${month}/${year}`);
        (async () => {
            try {
                const [empRes, statsRes, monthlyRes] = await Promise.all([
                    apiGet({ endpoint: endpoints.employee.show + employeeId }),
                    apiGet({
                        endpoint: endpoints.employeeAttendance.analysis,
                        queryParams: { employee_id: employeeId },
                    }),
                    apiGet({
                        endpoint: endpoints.employeeAttendance.attendance,
                        queryParams: { employee_id: employeeId, month, year },
                    }),
                ]);

                const empPayload = empRes.data?.data ?? empRes.data;
                if (!cancelled && empPayload && typeof empPayload === 'object') {
                    const e = empPayload as { name?: string; branch_name?: string };
                    setEmployeeName(e.name ?? '');
                    setBranchName(e.branch_name ?? '');
                }

                const statsPayload = statsRes.data?.data ?? statsRes.data;
                if (!cancelled && statsPayload && typeof statsPayload === 'object') {
                    setStats(statsPayload as Stats);
                }

                const monthlyPayload = monthlyRes.data?.data ?? monthlyRes.data;
                const rows = Array.isArray(monthlyPayload) ? monthlyPayload : [];
                const row = rows[0] as MonthlyEmployeeRow | undefined;
                if (!cancelled) {
                    setMonthly(row ?? null);
                }
            } catch {
                if (!cancelled) {
                    setStats(null);
                    setMonthly(null);
                }
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [employeeId, month, year]);

    const handlePrintSummary = useCallback(() => {
        openPrintableReport({
            title: `ملخص الحضور — ${employeeName || 'موظف'}`,
            subtitle: branchName ? `الفرع: ${branchName}` : undefined,
            rows: [
                { label: 'أيام السجلات (الإجمالي)', value: String(stats?.total_days ?? 0) },
                { label: 'أيام الحضور', value: String(stats?.present ?? 0) },
                { label: 'التأخير', value: String(stats?.late ?? 0) },
                { label: 'الغياب', value: String(stats?.absent ?? 0) },
                { label: 'إجازة', value: String(stats?.leave ?? 0) },
            ],
        });
    }, [employeeName, branchName, stats]);

    const handlePrintMonthly = useCallback(() => {
        if (!monthly?.attendance) {
            handlePrintSummary();
            return;
        }
        const sum = monthly.summary ?? {};
        const summaryRows = [
            { label: 'أيام الشهر', value: String(sum.total_days ?? '—') },
            { label: 'حضور', value: String(sum.present ?? 0) },
            { label: 'غياب', value: String(sum.absent ?? 0) },
            { label: 'تأخير', value: String(sum.late ?? 0) },
            { label: 'إجازة', value: String(sum.leave ?? 0) },
        ];

        const dayRows = Object.entries(monthly.attendance)
            .sort(([a], [b]) => a.localeCompare(b))
            .map(([date, v]) => ({
                date,
                status: statusAr(v?.status ?? ''),
                checkIn: v?.check_in ?? '—',
                checkOut: v?.check_out ?? '—',
                notes: v?.notes ?? '—',
            }));

        openPrintableAttendanceMonthly({
            title: `الحضور الشهري — ${(monthly.name ?? employeeName) || 'موظف'}`,
            subtitle: `الفترة: ${periodLabel} — ${monthly.branch ?? branchName ?? ''}`,
            summaryRows,
            dayRows,
        });
    }, [monthly, employeeName, branchName, periodLabel, handlePrintSummary]);

    return (
        <ReportSection
            icon={Clock3}
            title="الحضور والانصراف"
            description={`إحصائيات عامة وتفاصيل شهر ${periodLabel}. استخدم الطباعة ثم «حفظ كـ PDF» من نظام التشغيل إن لزم.`}
            actions={
                <>
                    <PrimaryButton type="button" onClick={handlePrintSummary} className="gap-2">
                        <Printer className="h-4 w-4 shrink-0" />
                        ملخص / PDF
                    </PrimaryButton>
                    <PrimaryButton type="button" onClick={handlePrintMonthly} className="gap-2 bg-slate-700 hover:bg-slate-800">
                        <CalendarClock className="h-4 w-4 shrink-0" />
                        تقرير الشهر
                    </PrimaryButton>
                </>
            }
        >
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4 lg:grid-cols-3">
                <NormalCard content={employeeName || '—'} title="الموظف" />
                <NormalCard content={branchName || '—'} title="الفرع" />
                <NormalCard content={String(stats?.total_days ?? 0)} title="إجمالي السجلات" subtitle="في النطاق" />
                <NormalCard content={String(stats?.present ?? 0)} title="أيام الحضور" subtitle="في النطاق" />
                <NormalCard content={String(stats?.late ?? 0)} title="التأخير" subtitle="أيام" />
                <NormalCard content={String(stats?.absent ?? 0)} title="الغياب" subtitle="أيام" />
                <NormalCard content={String(stats?.leave ?? 0)} title="إجازة" subtitle="أيام" />
                {monthly?.summary && (
                    <>
                        <NormalCard
                            content={String(monthly.summary.present ?? 0)}
                            title="حضور الشهر الحالي"
                            subtitle={periodLabel}
                        />
                        <NormalCard content={String(monthly.summary.absent ?? 0)} title="غياب الشهر" subtitle={periodLabel} />
                    </>
                )}
            </div>
        </ReportSection>
    );
}
